export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function visibleEdges(topic){const by=new Map([...topic.nodes,...topic.controls].map(n=>[n.id,n]));const out=[];for(const n of topic.nodes){function walk(id,parts,seen){if(seen.has(id))return;for(const e of topic.edges.filter(x=>x.from===id)){const next=[...parts,e],target=by.get(e.to);if(!target.kind)out.push({from:n.id,to:e.to,parts:next,label:next.map(x=>x.label).filter(Boolean).join('・'),kind:next.find(x=>x.kind!=='sequence')?.kind||'sequence'});else walk(e.to,next,new Set([...seen,id]));}}walk(n.id,[],new Set());}return out;}
